style.css:
@-moz-document domain("youtube.com") {
/* Target the main Subscribe button across video pages and channels */
    ytd-subscribe-button-renderer button,
    yt-subscribe-button-view-model button,
    #subscribe-button button,
    .yt-spec-button-shape-next--filled.yt-spec-button-shape-next--mono {
        background-color: #ff007f !important;
        background-image: linear-gradient(180deg, #ff4da6 0%, #ff007f 50%, #cc0066 100%) !important;
        color: #000000 !important;
        border: 2px solid #000000 !important;
        border-radius: 4px !important;
        box-shadow: 0 0 10px #ff007f, inset 0 1px 0 rgba(255, 255, 255, 0.6) !important;
        font-family: 'Creepster', 'Chiller', 'Impact', cursive, sans-serif !important;
        font-size: 18px !important;
        font-weight: 400 !important;
        letter-spacing: 2px !important;
        text-transform: uppercase !important;
        transition: all 0.15s ease-in-out !important;
    }

    /* Force the inner text span to stay black and keep the Creepster font */
    ytd-subscribe-button-renderer button .yt-core-attributed-string,
    yt-subscribe-button-view-model button .yt-core-attributed-string,
    #subscribe-button button span {
        font-family: 'Creepster', 'Chiller', 'Impact', cursive, sans-serif !important;
        color: #000000 !important;
        text-shadow: 0px 1px 0px rgba(255, 255, 255, 0.4) !important;
    }

    /* Hover Effect - Brighter Neon Glow */
    ytd-subscribe-button-renderer button:hover,
    yt-subscribe-button-view-model button:hover,
    #subscribe-button button:hover {
        background-color: #ff3399 !important;
        background-image: linear-gradient(180deg, #ff80bf 0%, #ff1a8c 50%, #e60073 100%) !important;
        box-shadow: 0 0 18px #ff007f, 0 0 5px #ffffff !important;
        transform: scale(1.03) !important;
    }

    /* Style for AFTER you click Subscribe ("Subscribed" state) */
    ytd-subscribe-button-renderer[subscribed] button,
    .yt-spec-button-shape-next--tonal.yt-spec-button-shape-next--mono {
        background-color: #1a1a1a !important;
        background-image: none !important;
        color: #ff007f !important;
        border: 2px solid #ff007f !important;
        box-shadow: 0 0 8px rgba(255, 0, 127, 0.5) !important;
        font-family: 'Creepster', 'Chiller', 'Impact', cursive, sans-serif !important;
        font-size: 18px !important;
        letter-spacing: 2px !important;
    }

    ytd-subscribe-button-renderer[subscribed] button .yt-core-attributed-string,
    .yt-spec-button-shape-next--tonal.yt-spec-button-shape-next--mono .yt-core-attributed-string {
        font-family: 'Creepster', 'Chiller', 'Impact', cursive, sans-serif !important;
        color: #ff007f !important;
        text-shadow: none !important;
    }
}
